type Challenge = { userId: string; expiresAt: number; attempts: number };
const challenges = new Map<string, Challenge>();
const selections = new Map<string, { userId: string; expiresAt: number }>();
const loginAttempts = new Map<string, { count: number; resetAt: number }>();

function cleanExpired(): void {
  const now = Date.now();
  for (const [key, value] of challenges) if (value.expiresAt <= now) challenges.delete(key);
  for (const [key, value] of selections) if (value.expiresAt <= now) selections.delete(key);
  for (const [key, value] of loginAttempts) if (value.resetAt <= now) loginAttempts.delete(key);
}

