function booleanRecord(value: unknown): value is Record<string, boolean> { return Boolean(value) && typeof value === 'object' && !Array.isArray(value) && Object.entries(value as object).every(([key, item]) => /^[a-z][a-z0-9_.-]{1,63}$/u.test(key) && typeof item === 'boolean'); }
