function validIssuedCertificate(result:Record<string,unknown>):boolean{if(!validCertificatePem(result.certificate_pem)||!validCertificatePem(result.ca_certificate_pem)||!validTLSCryptEnvelope(result.tls_crypt_key_envelope)||typeof result.serial!=='string'||typeof result.not_before!=='string'||typeof result.not_after!=='string')return false;try{const leaf=new X509Certificate(result.certificate_pem),ca=new X509Certificate(result.ca_certificate_pem),before=Date.parse(result.not_before),after=Date.parse(result.not_after);return ca.ca&&leaf.verify(ca.publicKey)&&leaf.serialNumber.toLowerCase()===result.serial&&Math.abs(Date.parse(leaf.validFrom)-before)<1000&&Math.abs(Date.parse(leaf.validTo)-after)<1000&&after>before;}catch{return false;}}
function credentialResponse(value:VpnCredentialView){return{id:value.id,environment_id:value.environmentId,state:value.state,...(value.serial?{serial:value.serial}:{}),...(value.certificatePem?{certificate_pem:value.certificatePem}:{}),...(value.caCertificatePem?{ca_certificate_pem:value.caCertificatePem}:{}),...(value.tlsCryptKeyEnvelope?{tls_crypt_key_envelope:value.tlsCryptKeyEnvelope}:{}),...(value.notBefore?{not_before:value.notBefore}:{}),...(value.notAfter?{not_after:value.notAfter}:{}),...(value.errorCode?{error_code:value.errorCode}:{})};}
