   @Post('v1/company/support/sessions')
   async requestSupport(@Req()request:FastifyRequest,@Body()raw:unknown,@Res()reply:FastifyReply):Promise<void>{
     const{tenantId,user}=await this.companyIdentity(request,'company.support.start'),body=objectBody(raw),allowedKeys=['device_id','mode','capabilities','consent_timeout_seconds'];
     if(Object.keys(body).some(key=>!allowedKeys.includes(key))||body.mode!=='assisted')throw new HttpException('unsupported_support_mode',422);
     const deviceId=requiredString(body,'device_id',64),rawCapabilities=body.capabilities;
     if(!/^[0-9a-f-]{36}$/iu.test(deviceId)||!Array.isArray(rawCapabilities)||rawCapabilities.length<1||rawCapabilities.length>SUPPORT_CAPABILITIES.length||rawCapabilities.some(value=>typeof value!=='string'||!(SUPPORT_CAPABILITIES as readonly string[]).includes(value))||new Set(rawCapabilities).size!==rawCapabilities.length)throw new HttpException('invalid_support_request',422);
     const timeout=body.consent_timeout_seconds===undefined?60:body.consent_timeout_seconds;
     if(!Number.isSafeInteger(timeout)||Number(timeout)<1||Number(timeout)>SUPPORT_CONSENT_TIMEOUT_MAX_SECONDS)throw new HttpException('invalid_support_timeout',422);
     if(!await this.company.supportEntitled(tenantId,user.id))throw new HttpException('support_not_entitled',403);
     const endpoint=(await this.devicesRepository.listDevices(tenantId)).find(item=>item.id===deviceId&&item.deviceKind==='endpoint'&&item.status==='approved');
     if(!endpoint)throw new HttpException('support_target_unavailable',409);
     const session=await this.support.createRequest({tenantId,deviceId,requesterUserId:user.id,capabilities:rawCapabilities as SupportCapability[],consentTimeoutSeconds:Number(timeout)});
     if(!session)throw new HttpException('forbidden',403);
     reply.code(201).send(supportSessionResponse(session));
   }

